        try {
            urlBuilder.setProtocol(url.split(":")[0]);
            urlBuilder.setHost(url.split("/")[0]);
            urlBuilder.setPath(url.split("/")[1].replaceAll("^\\/", ""));
            urlBuilder.addQuery(url.split("?")[1]);

            System.out.println("URL Builder: " + urlBuilder.toString());

        } catch (Exception e) {
            System.out.println("Failed to parse URL using UrlBuilder");
        }
    }

    public static void testUrl(Url parsedUrl) {
        try {
            if (!parsedUrl.getProtocol().equals("http") && !parsedUrl.getProtocol().equals("https")) {
                throw new Exception("Invalid protocol");
            }

            if (parsedUrl.getHost() == null || parsedUrl.getPath() == null) {
                throw new Exception("Missing host or path");
            }
        } catch (Exception e) {
            System.out.println("Failed to parse URL using Url");
        }
    }
